import React, { useState, useEffect, useCallback } from 'react';
import { 
  Box, 
  Typography, 
  Card, 
  CardContent, 
  CardMedia, 
  CircularProgress, 
  Button, 
  Tabs,
  Tab,
  Grid,
  Chip,
  Container,
  useTheme,
  useMediaQuery,
  CardActionArea,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  TextField,
  Paper,
  Stack,
  Divider,
  IconButton,
  Tooltip
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import { 
  Whatshot as WhatshotIcon, 
  Visibility as VisibilityIcon,
  NewReleases as BreakingNewsIcon,
  TrendingUp as TrendingIcon,
  ListAlt as AllNewsIcon,
  Category as CategoryIcon,
  ArrowForward as ArrowForwardIcon,
  ChatBubbleOutline as CommentIcon,
  BookmarkBorder as BookmarkIcon,
  Share as ShareIcon
} from '@mui/icons-material';
import { format, parseISO, isToday } from 'date-fns';
import { styled } from '@mui/material/styles';
import api from '../utils/api';

// Styled components
const StyledCard = styled(Card)(({ theme }) => ({
  height: '100%',
  display: 'flex',
  flexDirection: 'column',
  transition: 'transform 0.3s ease, box-shadow 0.3s ease',
  '&:hover': {
    transform: 'translateY(-4px)',
    boxShadow: theme.shadows[8],
  },
}));

const StyledChip = styled(Chip)(({ theme }) => ({
  position: 'absolute',
  top: 10,
  right: 10,
  backgroundColor: theme.palette.primary.main,
  color: theme.palette.primary.contrastText,
  fontWeight: 'bold',
  zIndex: 1,
}));

const TabPanel = (props) => {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`news-tabpanel-${index}`}
      aria-labelledby={`news-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box sx={{ py: 3 }}>
          {children}
        </Box>
      )}
    </div>
  );
};

const tabProps = (index) => ({
  id: `news-tab-${index}`,
  'aria-controls': `news-tabpanel-${index}`,
});

// Styled Components
const NewsCard = styled(Card)(({ theme }) => ({
  height: '100%',
  display: 'flex',
  flexDirection: 'column',
  transition: 'transform 0.3s ease, box-shadow 0.3s ease',
  '&:hover': {
    transform: 'translateY(-4px)',
    boxShadow: theme.shadows[8],
  },
}));

const NewsCardContent = styled(CardContent)(({ theme }) => ({
  flexGrow: 1,
  display: 'flex',
  flexDirection: 'column',
  padding: theme.spacing(2),
}));

const CategoryChip = styled(Chip)(({ theme }) => ({
  position: 'absolute',
  top: 12,
  right: 12,
  backgroundColor: theme.palette.primary.main,
  color: theme.palette.primary.contrastText,
  fontWeight: 'bold',
  zIndex: 1,
}));

// Available filters
const COUNTRIES = [
  { code: 'us', name: 'United States' },
  { code: 'in', name: 'India' },
  { code: 'gb', name: 'United Kingdom' },
  { code: 'ca', name: 'Canada' },
  { code: 'au', name: 'Australia' },
];

const CATEGORIES = [
  'general', 'business', 'entertainment', 'health', 'science', 'sports', 'technology'
];

const News = ({ activeTab = 0, onTabChange, tabLabels: propTabLabels, initialCategory = 'top' }) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  
  // Default tab labels if not provided
  const defaultTabLabels = [
    { label: 'Top Stories', icon: <CategoryIcon />, key: 'top' },
    { label: 'Most Viewed', icon: <VisibilityIcon />, key: 'most-viewed' },
    { label: 'Trending', icon: <TrendingIcon />, key: 'trending' },
    { label: 'Breaking', icon: <BreakingNewsIcon />, key: 'breaking' },
    { label: 'All News', icon: <AllNewsIcon />, key: 'all' }
  ];

  const tabLabels = propTabLabels || defaultTabLabels;
  
  // News categories state
  const [newsData, setNewsData] = useState({
    top: { articles: [], loading: true, page: 1, hasMore: true },
    'most-viewed': { articles: [], loading: false, page: 1, hasMore: true },
    trending: { articles: [], loading: false, page: 1, hasMore: true },
    breaking: { articles: [], loading: false, page: 1, hasMore: true },
    all: { articles: [], loading: false, page: 1, hasMore: true }
  });

  // Filter state
  const [filters, setFilters] = useState({
    country: 'us',
    category: 'general',
    searchQuery: ''
  });

  const handleFilterChange = (name, value) => {
    setFilters(prev => ({
      ...prev,
      [name]: value
    }));

    // Reset and refetch news when filters change
    const currentTabKey = tabLabels[activeTab].key;
    setNewsData(prev => ({
      ...prev,
      [currentTabKey]: { 
        ...prev[currentTabKey],
        articles: [],
        page: 1,
        hasMore: true
      }
    }));
    
    // Small delay to allow state to update before fetching
    setTimeout(() => {
      fetchNews(currentTabKey, 1, true);
    }, 100);
  };

  const fetchNews = useCallback(async (type, page = 1, isFilterChange = false) => {
    // Skip if already loading or no more data to load
    if ((newsData[type]?.loading) || (!newsData[type]?.hasMore && page > 1)) return;

    try {
      setNewsData(prev => ({
        ...prev,
        [type]: { 
          ...prev[type], 
          loading: true, 
          error: null 
        }
      }));

      // Simulate API call with mock data including filters
      const mockNews = Array(10).fill().map((_, i) => ({
        id: `${type}-${filters.country}-${filters.category}-${page}-${i}-${Date.now()}`,
        title: `${type.replace(/\b\w/g, l => l.toUpperCase())} News Item ${i + 1 + ((page - 1) * 10)} (${filters.country.toUpperCase()}, ${filters.category})`,
        description: `This is a ${filters.category} news article from ${COUNTRIES.find(c => c.code === filters.country)?.name || filters.country}.`,
        url: `#${type}-${i}`,
        urlToImage: `https://source.unsplash.com/random/400x300?${type},${filters.category},${filters.country},${i},${Date.now()}`,
        publishedAt: new Date(Date.now() - Math.random() * 7 * 24 * 60 * 60 * 1000).toISOString(),
        source: { 
          name: type === 'breaking' ? 'Breaking News' : 
                `${filters.category.charAt(0).toUpperCase() + filters.category.slice(1)} News` 
        },
        category: filters.category,
        country: filters.country,
        views: Math.floor(Math.random() * 10000)
      }));

      // Simulate network delay with cleanup
      let isMounted = true;
      await new Promise(resolve => setTimeout(resolve, 500));

      if (!isMounted) return;

      setNewsData(prev => ({
        ...prev,
        [type]: {
          ...prev[type],
          articles: page === 1 ? mockNews : [...(prev[type]?.articles || []), ...mockNews],
          loading: false,
          page: page + 1,
          hasMore: page < 3 // Limit to 3 pages for demo
        }
      }));

      return () => { isMounted = false; };
    } catch (error) {
      console.error(`Error fetching ${type}:`, error);
      setNewsData(prev => ({
        ...prev,
        [type]: { 
          ...prev[type],
          loading: false, 
          error: 'Failed to load news. Please try again later.' 
        }
      }));
    }
  }, [newsData, filters, activeTab]);

  const handleTabChangeInternal = (event, newValue) => {
    if (onTabChange) {
      onTabChange(event, newValue);
    } else {
      const type = tabLabels[newValue].key;
      if (newsData[type]?.articles?.length === 0) {
        fetchNews(type);
      }
    }
  };

  const loadMore = () => {
    const currentTab = tabLabels[activeTab].key;
    if (!newsData[currentTab].loading && newsData[currentTab].hasMore) {
      fetchNews(currentTab, newsData[currentTab].page);
    }
  };

  // Initial load and when category changes
  useEffect(() => {
    let isMounted = true;
    
    if (isMounted && initialCategory) {
      const type = tabLabels.find(tab => tab.key === initialCategory)?.key || 'top';
      if (newsData[type]?.articles?.length === 0) {
        fetchNews(type);
      }
    }

    return () => {
      isMounted = false;
    };
  }, [initialCategory, fetchNews]);

  // Format date
  const formatDate = (dateString) => {
    if (!dateString) return '';
    try {
      const date = new Date(dateString);
      return isToday(date) 
        ? format(date, 'h:mm a') 
        : format(date, 'MMM d, yyyy');
    } catch (e) {
      return '';
    }
  };

  const renderNewsCard = (article, index, type) => (
    <NewsCard>
      {type === 'breaking' && (
        <CategoryChip 
          size="small" 
          label="Breaking" 
          icon={<BreakingNewsIcon fontSize="small" />} 
        />
      )}
      
      <CardActionArea 
        component="a" 
        href={article.url} 
        target="_blank" 
        rel="noopener noreferrer"
        sx={{ flexGrow: 1, display: 'flex', flexDirection: 'column', alignItems: 'stretch' }}
      >
        <Box sx={{ position: 'relative', width: '100%', paddingTop: '56.25%' }}>
          <CardMedia
            component="img"
            image={article.urlToImage || 'https://via.placeholder.com/400x225?text=No+Image'}
            alt={article.title}
            sx={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              objectFit: 'cover',
            }}
          />
        </Box>
        
        <NewsCardContent>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
            <Chip 
              label={type === 'trending' ? 'Trending' : article.source?.name || 'News'} 
              size="small" 
              color={type === 'trending' ? 'secondary' : 'default'}
              sx={{ fontWeight: 600, fontSize: '0.7rem' }}
            />
            {type === 'mostViewed' && (
              <Box sx={{ display: 'flex', alignItems: 'center', color: 'text.secondary' }}>
                <VisibilityIcon fontSize="small" sx={{ mr: 0.5 }} />
                <Typography variant="caption">
                  {article.views?.toLocaleString() || '1.2k'}
                </Typography>
              </Box>
            )}
          </Box>
          
          <Typography 
            variant="subtitle1" 
            component="h3"
            sx={{
              fontWeight: 600,
              mb: 1,
              display: '-webkit-box',
              WebkitLineClamp: 3,
              WebkitBoxOrient: 'vertical',
              overflow: 'hidden',
              minHeight: '4.5em',
              lineHeight: 1.3,
            }}
          >
            {article.title}
          </Typography>
          
          <Typography 
            variant="body2" 
            color="text.secondary"
            sx={{
              mb: 2,
              display: '-webkit-box',
              WebkitLineClamp: 3,
              WebkitBoxOrient: 'vertical',
              overflow: 'hidden',
              minHeight: '4.5em',
              fontSize: '0.875rem',
            }}
          >
            {article.description || 'No description available'}
          </Typography>
          
          <Box sx={{ mt: 'auto', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <Typography variant="caption" color="text.secondary">
              {formatDate(article.publishedAt)}
            </Typography>
            <Button 
              size="small" 
              color="primary"
              endIcon={<ArrowForwardIcon />}
              sx={{ textTransform: 'none' }}
            >
              Read
            </Button>
          </Box>
        </NewsCardContent>
      </CardActionArea>
    </NewsCard>
  );

  const renderFilters = () => (
    <Paper elevation={0} sx={{ p: 2, mb: 3, bgcolor: 'background.paper', borderRadius: 2 }}>
      <Stack direction={isMobile ? 'column' : 'row'} spacing={2} alignItems="center">
        <FormControl size="small" sx={{ minWidth: 150 }}>
          <InputLabel>Country</InputLabel>
          <Select
            value={filters.country}
            label="Country"
            onChange={(e) => handleFilterChange('country', e.target.value)}
          >
            {COUNTRIES.map((country) => (
              <MenuItem key={country.code} value={country.code}>
                {country.name}
              </MenuItem>
            ))}
          </Select>
        </FormControl>

        <FormControl size="small" sx={{ minWidth: 150 }}>
          <InputLabel>Category</InputLabel>
          <Select
            value={filters.category}
            label="Category"
            onChange={(e) => handleFilterChange('category', e.target.value)}
          >
            {CATEGORIES.map((category) => (
              <MenuItem key={category} value={category}>
                {category.charAt(0).toUpperCase() + category.slice(1)}
              </MenuItem>
            ))}
          </Select>
        </FormControl>

        <TextField
          size="small"
          label="Search news..."
          value={filters.searchQuery}
          onChange={(e) => handleFilterChange('searchQuery', e.target.value)}
          sx={{ flexGrow: 1 }}
          placeholder="Type to search..."
        />
      </Stack>
    </Paper>
  );

  const renderTabContent = (type) => {
    const { articles, loading, hasMore, error } = newsData[type];
    
    if (loading && articles.length === 0) {
      return (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 8 }}>
          <CircularProgress />
        </Box>
      );
    }

    if (error) {
      return (
        <Box sx={{ textAlign: 'center', py: 4 }}>
          <Typography color="error" sx={{ mb: 2 }}>{error}</Typography>
          <Button 
            variant="outlined" 
            onClick={() => fetchNews(type, 1)}
            startIcon={<ArrowForwardIcon />}
          >
            Retry
          </Button>
        </Box>
      );
    }

    if (articles.length === 0) {
      return (
        <Box sx={{ textAlign: 'center', py: 4 }}>
          <Typography color="text.secondary">No articles found in this category.</Typography>
        </Box>
      );
    }

    return (
      <>
        <Grid container spacing={3}>
          {articles.map((article, index) => (
            <Grid key={`${type}-${index}`} xs={12} sm={6} md={4} lg={3}>
              {renderNewsCard(article, index, type)}
            </Grid>
          ))}
        </Grid>

        {loading && (
          <Box sx={{ display: 'flex', justifyContent: 'center', my: 4 }}>
            <CircularProgress />
          </Box>
        )}

        {!loading && hasMore && (
          <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
            <Button 
              variant="outlined" 
              onClick={() => loadMore()}
              disabled={loading}
              startIcon={!loading && <ArrowForwardIcon />}
            >
              {loading ? 'Loading...' : 'Load More'}
            </Button>
          </Box>
        )}
      </>
    );
  };

  return (
    <Box sx={{ py: 4, bgcolor: 'background.default' }}>
      <Container maxWidth="xl">
        {/* Header */}
        <Box sx={{ mb: 2, textAlign: 'center' }}>
          <Typography 
            variant="h3" 
            component="h1" 
            sx={{ 
              fontWeight: 700, 
              mb: 2,
              background: `linear-gradient(45deg, ${theme.palette.primary.main}, ${theme.palette.secondary.main})`,
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
              display: 'inline-block'
            }}
          >
            Latest News & Updates
          </Typography>
          <Typography variant="subtitle1" color="text.secondary" sx={{ maxWidth: 700, mx: 'auto' }}>
            Stay informed with the latest breaking news, trending stories, and most viewed articles from around the world.
          </Typography>
        </Box>

        {/* Tabs */}
        <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 4 }}>
          <Tabs
            value={activeTab}
            onChange={handleTabChangeInternal}
            variant="scrollable"
            scrollButtons="auto"
            allowScrollButtonsMobile
            aria-label="news categories"
            sx={{
              '& .MuiTabs-indicator': {
                height: 3,
                borderRadius: '3px 3px 0 0',
              },
              '& .MuiTab-root': {
                textTransform: 'none',
                fontWeight: 600,
                minHeight: 60,
                '&.Mui-selected': {
                  color: theme.palette.primary.main,
                },
                '&:hover': {
                  backgroundColor: 'action.hover',
                },
              },
            }}
          >
            {tabLabels.map((tab, index) => (
              <Tab 
                key={tab.key}
                icon={tab.icon}
                iconPosition="start"
                label={isMobile ? tab.label.split(' ')[0] : tab.label}
                {...a11yProps(index)}
                sx={{ minWidth: 'unset', px: 2 }}
              />
            ))}
          </Tabs>
        </Box>

        {/* Active Tab Content */}
        <Box sx={{ mb: 4 }}>
          {renderFilters()}
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            {tabLabels[activeTab].icon}
            <Typography variant="h5" sx={{ ml: 1, fontWeight: 600 }}>
              {tabLabels[activeTab].label}
            </Typography>
            <Chip 
              label={`${filters.category} • ${COUNTRIES.find(c => c.code === filters.country)?.name || filters.country}`} 
              size="small" 
              color="primary"
              variant="outlined"
              sx={{ ml: 2 }}
            />
          </Box>
          <Divider sx={{ mb: 3 }} />
        </Box>

        {/* Tab Content */}
        {tabLabels.map((tab, index) => (
          <TabPanel 
            key={tab.key} 
            value={activeTab} 
            index={index}
            dir={theme.direction}
          >
            {renderTabContent(tab.key)}
          </TabPanel>
        ))}
      </Container>
    </Box>
  );
};

// Helper function for accessibility
function a11yProps(index) {
  return {
    id: `news-tab-${index}`,
    'aria-controls': `news-tabpanel-${index}`,
  };
}

export default News;
